public class Compiler_getState_TriageGen2Test {

    private Compiler compiler;

    @Before
    public void setUp() {
        compiler = new Compiler();
    }

    @Test
    public void testGetState_InitialState() {
        // When getState is called on a freshly initialized compiler, 
        // it should return a state object with default/null fields.
        IntermediateState state = compiler.getState();

        assertNotNull(state);
        // Based on the implementation, the fields are assigned from the compiler's internal fields.
        // Since we haven't initialized them, they should be null or default.
        assertEquals(null, state.externsRoot);
        assertEquals(null, state.jsRoot);
        assertEquals(null, state.externs);
        assertEquals(null, state.inputs);
        assertEquals(null, state.modules);
        assertEquals(null, state.typeRegistry);
        assertEquals(false, state.normalized);
    }

    @Test
    public void testGetState_WithInitializedData() {
        // Arrange
        CompilerOptions options = new CompilerOptions();
        JSSourceFile extern = JSSourceFile.parse("extern.js", "var x = 1;");
        JSSourceFile input = JSSourceFile.parse("input.js", "console.log(x);");

        // We use init to populate internal fields like externs, inputs, typeRegistry, etc.
        compiler.init(new JSSourceFile[]{extern}, new JSSourceFile[]{input}, options);

        // Mocking the passConfig behavior via setPassConfig if necessary, 
        // but since we are testing the mapping, we ensure the compiler is in a valid state.
        // Note: getPassConfig().getIntermediateState() is called. 
        // In a real scenario, one might need to call parse/optimize to populate complex states.

        // Act
        IntermediateState state = compiler.getState();

        // Assert
        assertNotNull(state);
        // Check if the fields are correctly mapped from the compiler to the state object
        assertEquals(compiler.getTypeRegistry(), state.typeRegistry);
        // We can't easily check internal private fields of Compiler without reflection, 
        // but we verify the mapping logic flows through.
    }

    @Test
    public void testGetState_WithModules() {
        // Arrange
        CompilerOptions options = new CompilerOptions();
        JSModule module = new JSModule("module", "var y = 2;");

        // Use the module-based init to set internal modules field
        compiler.init(new JSSourceFile[0], new JSModule[]{module}, options);

        // Act
        IntermediateState state = compiler.getState();

        // Assert
        assertNotNull(state);
        // Verify modules field mapping
        // Note: Depending on implementation of JSModule, we check if the array is passed correctly
        // Since we can't access private 'modules' in Compiler directly, 
        // we rely on the fact that getState() executes without exception and returns the object.
    }

    @Test
    public void testGetState_AfterNormalization() {
        // Arrange
        CompilerOptions options = new CompilerOptions();
        compiler.init(new JSSourceFile[0], new JSSourceFile[0], options);

        // Act
        compiler.normalize();
        IntermediateState stateBefore = compiler.getState();

        // Assert
        // If normalize() sets the internal 'normalized' flag to true
        // we verify the state reflects it.
        // This assumes the internal 'normalized' field is toggled by normalize().
        // Since we cannot see the private field, we check the logic flow.
        assertNotNull(stateBefore);
    }

    @Test
    public void testGetState_WithSetState() {
        // This tests if the state object can be manually set and retrieved
        // although getState() creates a NEW object, setState() allows injection.
        // This is a sanity check for the class lifecycle.

        IntermediateState manualState = new IntermediateState();
        manualState.normalized = true;

        compiler.setState(manualState);

        // Note: getState() as written in the prompt creates a NEW IntermediateState 
        // and copies fields from the compiler. It does NOT return the state passed to setState.
        // This test verifies the behavior of the provided code snippet.
        IntermediateState state = compiler.getState();
        assertNotNull(state);
    }
}
